-- Run this in Supabase SQL Editor.
create table if not exists students (id bigint generated by default as identity primary key, name text not null, class_name text not null, subjects text default '', guardian_name text default '', guardian_phone text not null, active boolean default true, created_at timestamptz default now());
create table if not exists batches (id bigint generated by default as identity primary key, name text not null, class_name text not null, lecture_type text not null, start_time text, end_time text, created_at timestamptz default now());
create table if not exists attendance (id bigint generated by default as identity primary key, batch_id bigint references batches(id) on delete cascade, student_id bigint references students(id) on delete cascade, date date not null, status text not null check (status in ('present','absent')), time_in text, time_out text, created_at timestamptz default now(), unique(batch_id, student_id, date));
